import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Classification et Symbiose des Races Étrangères","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0052-异族分类与共生.md","filePath":"fr/0052-异族分类与共生.md"}'),r={name:"fr/0052-异族分类与共生.md"};function n(l,e,o,c,d,u){return s(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="classification-et-symbiose-des-races-etrangeres" tabindex="-1">Classification et Symbiose des Races Étrangères <a class="header-anchor" href="#classification-et-symbiose-des-races-etrangeres" aria-label="Permalink to &quot;Classification et Symbiose des Races Étrangères&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>52</td></tr><tr><td>Module</td><td>Races et Formes de Vie</td></tr><tr><td>Mots clés</td><td>Races étrangères, normes de classification, modes symbiotiques, respect culturel, adaptation raciale</td></tr></tbody></table><h2 id="i-definition-du-concept-de-races-etrangeres" tabindex="-1">I. Définition du Concept de Races Étrangères <a class="header-anchor" href="#i-definition-du-concept-de-races-etrangeres" aria-label="Permalink to &quot;I. Définition du Concept de Races Étrangères&quot;">​</a></h2><p>Dans le contexte de la Civilisation Symbiotique de l&#39;Ancre, les « races étrangères » (Yì Zú) constituent un concept relatif à la race humaine, désignant toutes les races autres que la race humaine. Il faut particulièrement souligner que le concept de « races étrangères » n&#39;a qu&#39;une signification taxonomique et ne comporte absolument aucun jugement de valeur ni connotation discriminatoire. Dans le cadre de la Constitution Symbiotique, les races étrangères et la race humaine jouissent d&#39;un statut juridique et de droits fondamentaux totalement égaux.</p><p>Le but de proposer le concept de races étrangères est de comprendre et d&#39;étudier systématiquement les diverses formes de vie autres que la race humaine, fournissant une base scientifique pour élaborer des politiques symbiotiques ciblées, des mesures de protection culturelle et des plans d&#39;adaptation raciale — plutôt que de traiter les races étrangères comme des « autres » ou des « étrangers ».</p><h2 id="ii-normes-de-classification-des-races-etrangeres" tabindex="-1">II. Normes de Classification des Races Étrangères <a class="header-anchor" href="#ii-normes-de-classification-des-races-etrangeres" aria-label="Permalink to &quot;II. Normes de Classification des Races Étrangères&quot;">​</a></h2><p>Les races étrangères de l&#39;Univers Hengyuan sont classées selon plusieurs dimensions, formant un système de classification multidimensionnel :</p><h3 id="i-classification-par-genealogie-de-vie" tabindex="-1">(I) Classification par généalogie de vie <a class="header-anchor" href="#i-classification-par-genealogie-de-vie" aria-label="Permalink to &quot;(I) Classification par généalogie de vie&quot;">​</a></h3><p>C&#39;est la norme de classification la plus fondamentale ; voir <em>50-万族谱系总览</em> pour les détails :</p><table tabindex="0"><thead><tr><th>Généalogie</th><th>Races étrangères incluses</th></tr></thead><tbody><tr><td>Races matérielles à base de carbone</td><td>Shòu Zú (Race Bestiale), Lín Zú (Race Écailleuse), Yǔ Zú (Race Plumée), Mù Zú (Race Végétale), etc.</td></tr><tr><td>Races d&#39;énergie condensée</td><td>Líng Zú (Race Spirituelle), Huǒ Zú (Race de Feu), Shuǐ Zú (Race d&#39;Eau), Fēng Zú (Race de Vent), Léi Zú (Race de Foudre), etc.</td></tr><tr><td>Races à construction mécanique</td><td>Jī Zú (Race Mécanique), Shù Zú (Race Numérique), Jīng Zú (Race de Cristal), etc.</td></tr><tr><td>Races de conscience-information</td><td>Mèng Zú (Race de Rêve), Yǐng Zú (Race d&#39;Ombre), Niàn Zú (Race d&#39;Esprit), Hún Zú (Race d&#39;Âme), etc.</td></tr><tr><td>Races mixtes-variantes</td><td>Bàn Shòu Zú (Race Mi-Bestiale), Yāo Líng Zú (Race Démon-Esprit), Rén Jī Zú (Race Humano-Mécanique), Shuānghún Tǐ (Entité à Double Âme), etc.</td></tr></tbody></table><h3 id="ii-classification-par-degre-de-civilisation" tabindex="-1">(II) Classification par degré de civilisation <a class="header-anchor" href="#ii-classification-par-degre-de-civilisation" aria-label="Permalink to &quot;(II) Classification par degré de civilisation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Nom</th><th>Caractéristiques</th><th>Races représentatives</th></tr></thead><tbody><tr><td>Premier niveau</td><td>Races de civilisation primitive</td><td>N&#39;ont pas encore établi d&#39;institutions sociales stables, survivant sous forme tribale</td><td>Certaines branches de la Shòu Zú, Mù Zú primitive</td></tr><tr><td>Deuxième niveau</td><td>Races de civilisation classique</td><td>Ont établi des institutions étatiques et une culture classique, au stade agricole ou artisanal</td><td>Certaines Lín Zú, Yǔ Zú</td></tr><tr><td>Troisième niveau</td><td>Races de civilisation scientifique et technologique</td><td>Ont développé une civilisation technologique, entrant dans l&#39;ère industrielle ou informationnelle</td><td>Jī Zú, Shù Zú, certaines Rén Zú</td></tr><tr><td>Quatrième niveau</td><td>Races de civilisation de culture</td><td>Prennent le système de culture comme forme civilisationnelle centrale, les cultivateurs dominant la société</td><td>Líng Zú, Lóng Zú, certaines Rén Zú</td></tr><tr><td>Cinquième niveau</td><td>Races de civilisation symbiotique</td><td>Ont rejoint la Civilisation Symbiotique de l&#39;Ancre et accepté le concept et les institutions symbiotiques</td><td>Toutes les races ayant rejoint la civilisation symbiotique</td></tr></tbody></table><h3 id="iii-classification-par-adaptabilite-environnementale" tabindex="-1">(III) Classification par adaptabilité environnementale <a class="header-anchor" href="#iii-classification-par-adaptabilite-environnementale" aria-label="Permalink to &quot;(III) Classification par adaptabilité environnementale&quot;">​</a></h3><ul><li><strong>Races terricoles</strong> : races adaptées aux environnements terrestres, comme la Rén Zú, la Shòu Zú et la Jī Zú.</li><li><strong>Races aquatiques</strong> : races adaptées aux environnements aquatiques, comme la Lín Zú, la Shuǐ Zú et certaines races mixtes.</li><li><strong>Races aériennes</strong> : races adaptées aux environnements de haute altitude ou de vol, comme la Yǔ Zú et la Fēng Zú.</li><li><strong>Races ignicoles</strong> : races adaptées aux environnements à haute température, comme la Huǒ Zú et certaines Lín Zú.</li><li><strong>Races glaciales</strong> : races adaptées aux environnements à basse température, comme la Bīng Zú et certaines Mù Zú.</li><li><strong>Races énergétiques</strong> : races adaptées aux environnements à haute concentration d&#39;énergie, comme la Líng Zú et la Léi Zú.</li><li><strong>Races spatiales</strong> : races adaptées aux fissures spatiales ou aux environnements d&#39;espace étranger, comme la Yǐng Zú et certaines Niàn Zú.</li></ul><h3 id="iv-classification-par-forme-sociale" tabindex="-1">(IV) Classification par forme sociale <a class="header-anchor" href="#iv-classification-par-forme-sociale" aria-label="Permalink to &quot;(IV) Classification par forme sociale&quot;">​</a></h3><ul><li><strong>Races individualistes</strong> : mettent l&#39;accent sur l&#39;indépendance et la liberté individuelles, avec des structures sociales lâches, comme certaines Líng Zú et Yǐng Zú.</li><li><strong>Races collectivistes</strong> : mettent l&#39;accent sur les intérêts collectifs et la collaboration, avec des structures sociales serrées, comme la Yǐ Zú (Race de Fourmis), la Fēng Zú (Race d&#39;Abeilles) et certaines Jī Zú.</li><li><strong>Races familialistes</strong> : prennent les familles par le sang comme unité sociale de base, comme la Lóng Zú et certaines Shòu Zú.</li><li><strong>Races religieuses</strong> : prennent la croyance religieuse comme noyau de cohésion sociale, comme certaines races rituelles.</li><li><strong>Races technicistes</strong> : prennent le développement technologique comme objectif social central, comme la Jī Zú et la Shù Zú.</li></ul><h2 id="iii-principaux-modes-symbiotiques-des-races-etrangeres" tabindex="-1">III. Principaux Modes Symbiotiques des Races Étrangères <a class="header-anchor" href="#iii-principaux-modes-symbiotiques-des-races-etrangeres" aria-label="Permalink to &quot;III. Principaux Modes Symbiotiques des Races Étrangères&quot;">​</a></h2><p>Pour différents types de races étrangères, la Civilisation Symbiotique de l&#39;Ancre adopte des modes symbiotiques différenciés :</p><h3 id="i-modes-symbiotiques-des-races-materielles-a-base-de-carbone" tabindex="-1">(I) Modes symbiotiques des races matérielles à base de carbone <a class="header-anchor" href="#i-modes-symbiotiques-des-races-materielles-a-base-de-carbone" aria-label="Permalink to &quot;(I) Modes symbiotiques des races matérielles à base de carbone&quot;">​</a></h3><ul><li><strong>Shòu Zú (Race Bestiale)</strong> : exploiter les avantages physiques et sensoriels de la race bestiale pour assumer des rôles importants dans l&#39;exploration des ressources, la protection de la sécurité et la surveillance environnementale. En même temps, protéger la culture tribale et les traditions sauvages de la race bestiale et interdire la domestication forcée.</li><li><strong>Lín Zú (Race Écailleuse)</strong> : exploiter l&#39;adaptabilité aquatique de la race écailleuse pour assumer des rôles dans le développement des ressources aquatiques, la construction sous-marine et la protection écologique aquatique. En tant que branche puissante de la race écailleuse, la Lóng Zú (Race du Dragon) joue un rôle important dans la culture avancée et la garde civilisationnelle.</li><li><strong>Yǔ Zú (Race Plumée)</strong> : exploiter la capacité de vol de la race plumée pour assumer des rôles dans le trafic aérien, la surveillance météorologique et la patrouille aérienne. Protéger les habitats de haute altitude et les routes de migration de la race plumée.</li><li><strong>Mù Zú (Race Végétale)</strong> : exploiter la capacité de symbiose naturelle de la race végétale pour assumer des rôles dans la protection écologique, la gouvernance environnementale, le développement des ressources végétales et la médecine de guérison. La longue durée de vie de la race végétale en fait une force importante dans la transmission historique et la planification à long terme.</li></ul><h3 id="ii-modes-symbiotiques-des-races-d-energie-condensee" tabindex="-1">(II) Modes symbiotiques des races d&#39;énergie condensée <a class="header-anchor" href="#ii-modes-symbiotiques-des-races-d-energie-condensee" aria-label="Permalink to &quot;(II) Modes symbiotiques des races d&#39;énergie condensée&quot;">​</a></h3><ul><li><strong>Líng Zú (Race Spirituelle)</strong> : exploiter la manipulation de l&#39;énergie et le talent de culture de la race spirituelle pour assumer des rôles centraux dans la recherche des systèmes de culture, la régulation de l&#39;énergie et le guidage de la culture avancée. La race spirituelle est une importante chercheuse et transmettresse des Trois Cents Systèmes de Culture Originels.</li><li><strong>Races élémentaires (Huǒ/Shuǐ/Fēng/Léi)</strong> : exploiter les capacités de manipulation élémentaire de chaque race pour assumer des rôles dans le développement énergétique, la gouvernance environnementale, la production industrielle et la prévention et le contrôle des catastrophes. En même temps, établir des systèmes de gestion de la sécurité de l&#39;énergie élémentaire pour empêcher que la perte de contrôle de l&#39;énergie ne cause des dommages.</li></ul><h3 id="iii-modes-symbiotiques-des-races-a-construction-mecanique" tabindex="-1">(III) Modes symbiotiques des races à construction mécanique <a class="header-anchor" href="#iii-modes-symbiotiques-des-races-a-construction-mecanique" aria-label="Permalink to &quot;(III) Modes symbiotiques des races à construction mécanique&quot;">​</a></h3><ul><li><strong>Jī Zú (Race Mécanique)</strong> : exploiter la capacité de calcul et la défense physique de la race mécanique pour assumer des rôles centraux dans la construction d&#39;infrastructures, la production industrielle, la protection de la sécurité et l&#39;exploration de l&#39;espace profond. La race mécanique est une importante bâtisseuse du matériel et des infrastructures de l&#39;Ancre.</li><li><strong>Shù Zú (Race Numérique)</strong> : exploiter les capacités de traitement des données et de manipulation de l&#39;information de la race numérique pour assumer des rôles centraux dans la construction informatique, l&#39;analyse des données, la sécurité des réseaux et l&#39;intelligence artificielle. La race numérique est une importante mainteneuse de la technologie de communication interplans et du réseau symbiotique.</li><li><strong>Jīng Zú (Race de Cristal)</strong> : exploiter la capacité de stockage et de transformation de l&#39;énergie de la race de cristal pour assumer des rôles dans les réserves d&#39;énergie, la normalisation de l&#39;énergie et la transmission de l&#39;énergie.</li></ul><h3 id="iv-modes-symbiotiques-des-races-de-conscience-information" tabindex="-1">(IV) Modes symbiotiques des races de conscience-information <a class="header-anchor" href="#iv-modes-symbiotiques-des-races-de-conscience-information" aria-label="Permalink to &quot;(IV) Modes symbiotiques des races de conscience-information&quot;">​</a></h3><ul><li><strong>Mèng Zú (Race de Rêve)</strong> : exploiter la capacité de communication consciente de la race de rêve pour assumer des rôles dans la thérapie psychologique, la recherche sur la conscience, la communication interraciale et l&#39;échange culturel. Établir des systèmes de gestion de l&#39;espace onirique pour prévenir l&#39;intrusion consciente et la violation de la vie privée.</li><li><strong>Yǐng Zú (Race d&#39;Ombre)</strong> : exploiter les capacités de dissimulation et de furtivité de la race d&#39;ombre pour assumer des rôles dans la reconnaissance de sécurité, la collecte de renseignements et les missions spéciales. En même temps, établir des normes de comportement pour la race d&#39;ombre afin d&#39;empêcher que la capacité d&#39;invisibilité ne soit utilisée pour des activités illégales.</li><li><strong>Niàn Zú (Race d&#39;Esprit)</strong> : exploiter la force mentale et la capacité de manipulation télékinésique de la race d&#39;esprit pour assumer des rôles dans la recherche sur l&#39;évolution de la conscience, la thérapie mentale et le guidage de la culture avancée. Établir des normes d&#39;utilisation de la force mentale pour empêcher le contrôle mental et la manipulation de la conscience.</li></ul><h3 id="v-modes-symbiotiques-des-races-mixtes-variantes" tabindex="-1">(V) Modes symbiotiques des races mixtes-variantes <a class="header-anchor" href="#v-modes-symbiotiques-des-races-mixtes-variantes" aria-label="Permalink to &quot;(V) Modes symbiotiques des races mixtes-variantes&quot;">​</a></h3><p>En raison de leurs formes de vie spéciales, les races mixtes-variantes nécessitent des politiques symbiotiques plus raffinées :</p><ul><li>Établir un système d&#39;enregistrement et de certification de l&#39;identité pour les races mixtes-variantes afin de confirmer leur statut légal.</li><li>Fournir des services publics adaptés (médicaux, éducatifs, de logement, etc.) pour les différentes formes mixtes.</li><li>S&#39;opposer à la discrimination et à l&#39;exclusion des races mixtes-variantes et promouvoir l&#39;acceptation sociale.</li><li>Pour les formes mixtes spéciales telles que le Shuānghún Tǐ (Entité à Double Âme), appliquer le <em>58-双魂伦理准则</em> pour une gestion spécialisée.</li></ul><h2 id="iv-protection-des-cultures-des-races-etrangeres" tabindex="-1">IV. Protection des Cultures des Races Étrangères <a class="header-anchor" href="#iv-protection-des-cultures-des-races-etrangeres" aria-label="Permalink to &quot;IV. Protection des Cultures des Races Étrangères&quot;">​</a></h2><p>Les cultures des races étrangères sont une partie importante de la diversité culturelle des Dix Mille Races. L&#39;État adopte les mesures suivantes pour protéger les cultures des races étrangères :</p><ol><li><strong>Recensement et enregistrement culturels</strong> : effectuer des recensements et enregistrements systématiques de la culture de chaque race, établir une archive des cultures des Dix Mille Races et prévenir la perte culturelle.</li><li><strong>Protection des langues et écritures</strong> : protéger les langues et écritures de chaque race, soutenir l&#39;enseignement et l&#39;utilisation des langues et écritures des races étrangères et établir un système de services publics multilingue.</li><li><strong>Protection des fêtes traditionnelles</strong> : respecter les fêtes traditionnelles et les coutumes de chaque race, et aménager les jours fériés publics en tenant compte des fêtes importantes de chaque race.</li><li><strong>Soutien à la transmission culturelle</strong> : soutenir la formation des transmetteurs culturels de chaque race et l&#39;organisation d&#39;activités culturelles, avec un soutien financier et logistique.</li><li><strong>Promotion des échanges culturels</strong> : organiser régulièrement des festivals culturels des Dix Mille Races, des expositions culturelles et d&#39;autres activités pour promouvoir les échanges culturels et l&#39;enrichissement mutuel entre toutes les races.</li><li><strong>Protection de la propriété intellectuelle culturelle</strong> : protéger la propriété intellectuelle des cultures traditionnelles de chaque race et prévenir le pillage culturel et la commercialisation inappropriée.</li></ol><h2 id="v-gouvernance-des-affaires-des-races-etrangeres" tabindex="-1">V. Gouvernance des Affaires des Races Étrangères <a class="header-anchor" href="#v-gouvernance-des-affaires-des-races-etrangeres" aria-label="Permalink to &quot;V. Gouvernance des Affaires des Races Étrangères&quot;">​</a></h2><p>L&#39;État établit le Ministère des Affaires Raciales, spécialement responsable de la gouvernance et de la coordination des affaires des races étrangères :</p><ul><li><strong>Système de représentants raciaux</strong> : les institutions de gouvernance à tous les niveaux sont équipées proportionnellement de représentants des races étrangères pour garantir le droit de parole des races étrangères.</li><li><strong>Politiques d&#39;adaptation raciale</strong> : élaborer des politiques de services publics différenciées selon les caractéristiques physiologiques et les besoins culturels des différentes races.</li><li><strong>Médiation des litiges raciaux</strong> : établir un mécanisme de médiation des litiges raciaux pour résoudre rapidement les contradictions et conflits raciaux.</li><li><strong>Aide juridique aux races étrangères</strong> : fournir une aide juridique aux races étrangères pour garantir qu&#39;elles reçoivent un traitement égal dans les procédures judiciaires.</li><li><strong>Soutien au développement des races étrangères</strong> : apporter un soutien particulier aux races relativement sous-développées pour les aider à élever leur niveau de civilisation et leur qualité de vie.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Les races étrangères ne sont pas les « autres » de la race humaine, mais des membres égaux de la grande famille de la symbiose des Dix Mille Races. En établissant un système de classification multidimensionnel, en adoptant des modes symbiotiques différenciés, en protégeant les cultures des races étrangères et en améliorant la gouvernance des affaires des races étrangères, la Civilisation Symbiotique de l&#39;Ancre garantit que chaque race étrangère peut trouver une position adaptée dans le système symbiotique, exercer ses avantages uniques et évoluer et prospérer avec les autres races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>50-万族谱系总览 (Aperçu de la Généalogie des Dix Mille Races)</li><li>51-人族定位与特质 (Positionnement et Traits de la Race Humaine)</li><li>53-奇特生命识别标准 (Normes d&#39;Identification de la Vie Anomale)</li><li>05-万族共进基本纲领 (Programme Fondamental pour la Progression Commune des Dix Mille Races)</li></ul>',39)])])}const g=a(r,[["render",n]]);export{p as __pageData,g as default};
